          "notes": [{"id":"mishna-shabbat-8-2-n1","owner":"mishna-shabbat-8-2","role":"meaning-qualification","placement":"outside-source-disclosure","he":"פליטון הוא בושם; המשנה אינה מפרטת את מרכיביו.","en":"The flask contains perfume; the Mishna does not specify its ingredients.","sourceTextSHA256":"6ae904bc48ba6e9979d6ec5f7b5cd914d188c1350f8b19fe21229a44b186b409","span":{"start":322,"end":338,"endExclusive":true,"unit":"unicode-codepoint"}},{"id":"mishna-shabbat-8-2-meaning-qualification-2","owner":"mishna-shabbat-8-2","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"6ae904bc48ba6e9979d6ec5f7b5cd914d188c1350f8b19fe21229a44b186b409","span":{"start":0,"end":339,"endExclusive":true,"unit":"unicode-codepoint"},"he":"נפה וכברה הם כלים נפרדים. חלופת מידת המנעל של רבי יהודה נסמכת לגמי, לא לעשיית מנעל מחבל.","en":"The fine and coarse sieves remain distinct. רבי יהודה’s shoe-measuring alternative attaches to the rush, not making a shoe from rope."},{"id":"mishna-shabbat-8-2-source-qualification-3","owner":"mishna-shabbat-8-2","role":"source-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"6ae904bc48ba6e9979d6ec5f7b5cd914d188c1350f8b19fe21229a44b186b409","span":{"start":0,"end":339,"endExclusive":true,"unit":"unicode-codepoint"},"he":"קשר מוכסין הוא פתק מכס כתוב לפי ברטנורא, לא קשר בחבל. פליטון מתורגם כבושם באופן כללי; מרכיביו אינם מזוהים בוודאות.","en":"The customs token is written, following Bartenura, not a knot in rope. The flask’s contents are generally rendered perfume; its ingredients are not securely identified."},{"id":"mishna-shabbat-8-2-meaning-qualification-4","owner":"mishna-shabbat-8-2","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"6ae904bc48ba6e9979d6ec5f7b5cd914d188c1350f8b19fe21229a44b186b409","span":{"start":0,"end":339,"endExclusive":true,"unit":"unicode-codepoint"},"he":"השיעורים, המחלוקות והתנאים הם ביאור הנוסח ופירושו, לא פסיקה למעשה או המלצה רפואית.","en":"The measures, disputes and conditions explain the received text and commentary, not practical legal or medical advice."}]
