          "notes": [{"id":"mishna-shabbat-8-3-meaning-qualification-1","owner":"mishna-shabbat-8-3","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"24381c3849cd7dc8360ac931fcfa9e46ad504be8234115597772ed45e5e81e75","span":{"start":0,"end":204,"endExclusive":true,"unit":"unicode-codepoint"},"he":"המשנה אומרת לעשות קמע; ברטנורא מזהה את העור ככיסוי, לא בהכרח המצע לכתיבת תוכן הקמע.","en":"The Mishna says to make an amulet; Bartenura identifies the hide as its covering, not necessarily the surface for its text."},{"id":"mishna-shabbat-8-3-meaning-qualification-2","owner":"mishna-shabbat-8-3","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"24381c3849cd7dc8360ac931fcfa9e46ad504be8234115597772ed45e5e81e75","span":{"start":0,"end":204,"endExclusive":true,"unit":"unicode-codepoint"},"he":"שמע ישראל מציין פרשה, לא רק שתי מילות פתיחה כשיעור כתיבה. שתי אותיות ועין אחת שיעורים נפרדים; דין האותיות הגדולות בפתק המכס אינו מועבר לכאן.","en":"‘Hear, Israel’ identifies a passage, not merely two opening words as the writing measure. Two letters and one eye are distinct measures; the customs token’s large-letter condition is not imported."},{"id":"mishna-shabbat-8-3-meaning-qualification-3","owner":"mishna-shabbat-8-3","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"24381c3849cd7dc8360ac931fcfa9e46ad504be8234115597772ed45e5e81e75","span":{"start":0,"end":204,"endExclusive":true,"unit":"unicode-codepoint"},"he":"השיעורים, המחלוקות והתנאים הם ביאור הנוסח ופירושו, לא פסיקה למעשה או המלצה רפואית.","en":"The measures, disputes and conditions explain the received text and commentary, not practical legal or medical advice."}]
