          "notes": [{"id":"mishna-shabbat-8-6-n1","owner":"mishna-shabbat-8-6","role":"meaning-qualification","placement":"outside-source-disclosure","he":"כרכר הוא כלי אורגים; הברטנורא מתאר העברה על השתי והכאת החוטים. התיאור אינו מזהה כאן דגם מסוים של כלי מודרני.","en":"This is a weaver's implement. Bartenura describes passing it over the warp and beating the threads, without identifying a particular modern tool model.","sourceTextSHA256":"7d095359d5c07af8223134bb547a71999cf55393b8e4770fcd0f70db1b27650a","span":{"start":121,"end":138,"endExclusive":true,"unit":"unicode-codepoint"}},{"id":"mishna-shabbat-8-6-source-qualification-2","owner":"mishna-shabbat-8-6","role":"source-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"7d095359d5c07af8223134bb547a71999cf55393b8e4770fcd0f70db1b27650a","span":{"start":0,"end":247,"endExclusive":true,"unit":"unicode-codepoint"},"he":"חף הוא שן מפתח לפי ברטנורא. כרכר מתואר ככלי אורגים הפועל בשתי, בלי זיהוי ודאי כדגם מודרני של בוכייר או כלי אחר.","en":"The key-tooth follows Bartenura’s חף explanation. The weaver’s implement acts on the warp without secure identification as a particular modern shuttle or other tool."},{"id":"mishna-shabbat-8-6-meaning-qualification-3","owner":"mishna-shabbat-8-6","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"7d095359d5c07af8223134bb547a71999cf55393b8e4770fcd0f70db1b27650a","span":{"start":0,"end":247,"endExclusive":true,"unit":"unicode-codepoint"},"he":"צרור או אבן ועוף לעומת בהמה הן חלופות, לא שיעור מאוחד. ברטנורא דן בהברחה ובקול שמספיק לעוף; אין כאן הוראה לפגוע בבעלי חיים.","en":"Pebble or stone and bird versus animal are alternatives, not one combined measure. Bartenura discusses driving away and sound alone sufficing for a bird; this is not an instruction to harm animals."},{"id":"mishna-shabbat-8-6-meaning-qualification-4","owner":"mishna-shabbat-8-6","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"7d095359d5c07af8223134bb547a71999cf55393b8e4770fcd0f70db1b27650a","span":{"start":0,"end":247,"endExclusive":true,"unit":"unicode-codepoint"},"he":"השיעורים, המחלוקות והתנאים הם ביאור הנוסח ופירושו, לא פסיקה למעשה או המלצה רפואית.","en":"The measures, disputes and conditions explain the received text and commentary, not practical legal or medical advice."}]
