          "notes": [{"id":"mishna-zevachim-7-2/Q1","owner":"mishna-zevachim-7-2","role":"meaning-qualification","placement":"outside-source-disclosure","he":"׳ובלבד שלא עלתה לבעלים׳ מציין כאן כשרות בלי יציאת הבעלים ידי חובתם, כפי שמבאר הברטנורא. אין זה תנאי שלפיו כבר התקיימה חובתם. שינוי השם במקרה זה שונה משינוי המעשה בשני המקרים הפסולים שאחריו.","en":"‘Provided that it has not counted for the owners’ means here that the offering is valid without fulfilling their obligation, as Bartenura explains. It does not mean that their obligation has already been fulfilled. This changed-designation case differs from the two following invalid changed-procedure cases.","sourceTextSHA256":"880392c0bfdcda9a36ba34b486e65f8ef83d140d22c486fb1b9f1131eeeb6a51","span":{"start":118,"end":166,"endExclusive":true,"unit":"unicode-codepoint"}},{"id":"mishna-zevachim-7-2-meaning-qualification-2","owner":"mishna-zevachim-7-2","role":"meaning-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"880392c0bfdcda9a36ba34b486e65f8ef83d140d22c486fb1b9f1131eeeb6a51","span":{"start":0,"end":299,"endExclusive":true,"unit":"unicode-codepoint"},"he":"׳ובלבד שלא עלתה לבעלים׳ אינו קיום חובתם; הפירוש מסביר כשרות בלי יציאתם ידי חובה. שינוי השם נבדל משני מקרי שינוי המעשה, וכל המקרים למטה פסולים.","en":"‘Provided that it has not counted for the owners’ is not fulfillment of their obligation; the commentary explains validity without discharge. Changed designation differs from the two changed-procedure cases, and all cases below remain invalid."},{"id":"mishna-zevachim-7-2-source-qualification-3","owner":"mishna-zevachim-7-2","role":"source-qualification","placement":"outside-source-disclosure","sourceTextSHA256":"880392c0bfdcda9a36ba34b486e65f8ef83d140d22c486fb1b9f1131eeeb6a51","span":{"start":0,"end":299,"endExclusive":true,"unit":"unicode-codepoint"},"he":"המספור וגבולות הקריאה אינם מספור דפוס מאומת; ההפניה הקודמת ו:ו לעומת ז:א נותרה בלתי מוכרעת. מהדורת המקור ומקור הניקוד לא נתבררו, ודפי דפוס תואמים לא נבדקו.","en":"Numbering and reading boundaries are not authenticated print numbering; the earlier 6:6 versus 7:1 reference remains unresolved. The original edition and pointing origin remain unestablished; matching printed pages have not been inspected."}]
